// Scope decisions baked into this filter (see header comment above for
// details and dates):
//   1. Water Tanks are out of active use right now (Nelson, 2026-08-25) —
//      only Water Points ("P") are in the picker.
//   2. Private Water Points are out of scope entirely (Edu, 2026-08-25) —
//      only isPublic===1 assets are in the picker.
// The raw 1,717-row list above stays in the file either way; dropping
// either half of this filter brings the corresponding assets back.
const WATER_ASSETS = WATER_ASSET_ROWS
  .filter(r => r[1] === "P" && r[10] === 1)
  .map(r => ({
    tag: r[0], type: r[1], ward: r[2], village: r[3], sub: r[4], loc: r[5],
    lat: r[6], lon: r[7], volunteer: r[8], routeOrder: r[9], public: r[10] === 1,
    group: r[11],
  }));

/* ==================================================================
   LOOKUPS for the cascading Ward -> Village -> Sub-Village -> Asset Tag
   picker on the water_point setup screen. Sub-Village is optional: pass
   "" (or omit) to match assets regardless of sub-village.
   ================================================================== */
function uniqSorted(values){
  return Array.from(new Set(values)).sort((a,b) => a.localeCompare(b));
}

function getWards(){
  return uniqSorted(WATER_ASSETS.map(a => a.ward).filter(Boolean));
}
function getVillages(ward){
  if(!ward) return [];
  return uniqSorted(WATER_ASSETS.filter(a => a.ward === ward).map(a => a.village).filter(Boolean));
}
function getSubVillages(ward, village){
  if(!ward || !village) return [];
  return uniqSorted(
    WATER_ASSETS.filter(a => a.ward === ward && a.village === village).map(a => a.sub).filter(Boolean)
  );
}
/** Asset Tag options for the current Ward/Village (+ optional Sub-Village). */
function getAssets(ward, village, subVillage){
  if(!ward || !village) return [];
  return WATER_ASSETS
    .filter(a => a.ward === ward && a.village === village && (!subVillage || a.sub === subVillage))
    .sort((a,b) => a.tag.localeCompare(b.tag));
}
function findAsset(tag){
  return WATER_ASSETS.find(a => a.tag === tag) || null;
}

/* ==================================================================
   VOLUNTEER ROUTES — precomputed groupings, see the header note above.
   Each volunteer covers one group per field day (4 groups total). A
   volunteer must pick which day/group they're working before "My route"
   can show anything, since the same volunteer's groups point at
   completely different places on different days.
   ================================================================== */
function getVolunteers(){
  return VOLUNTEERS.slice();
}

/**
 * The groups assigned to a volunteer, one per field day, sorted by day.
 * Returns `[]` for a volunteer with no groups (e.g. "Teste"). Each entry:
 * `{ group, day, count }` — `count` is how many Water Points are in that
 * group (regardless of GPS availability), for a quick preview in the
 * picker.
 */
function getVolunteerGroups(volunteer){
  const byGroup = new Map();
  for(const a of WATER_ASSETS){
    if(a.volunteer !== volunteer || a.group == null) continue;
    byGroup.set(a.group, (byGroup.get(a.group) || 0) + 1);
  }
  return Array.from(byGroup.entries())
    .map(([group, count]) => ({ group, day: groupDay(group), count }))
    .sort((a,b) => a.group - b.group);
}

/**
 * One volunteer's work for a single group: `ordered` is that group's
 * Water Points with a known location, sorted by visiting order
 * (routeOrder); `unordered` is the rest of the group (no GPS on file),
 * sorted by Asset Tag. Returns both empty if the volunteer has no such
 * group (or `group` is omitted/invalid).
 */
function getRoute(volunteer, group){
  const mine = WATER_ASSETS.filter(a => a.volunteer === volunteer && a.group === group);
  return {
    ordered: mine.filter(a => a.routeOrder != null).sort((a,b) => a.routeOrder - b.routeOrder),
    unordered: mine.filter(a => a.routeOrder == null).sort((a,b) => a.tag.localeCompare(b.tag)),
  };
}

export {
  WATER_ASSETS, VOLUNTEERS,
  getWards, getVillages, getSubVillages, getAssets, findAsset,
  getVolunteers, getVolunteerGroups, getRoute, groupDay,
};
